     "t": "こんにちわ！\n\n昨日は公演が終わってからたこ焼きを、食べに行きました(〃≧ ≦〃)\n\nもーのすごく！美味しかったです！\n\n美味しすぎて、写真撮るの忘れちゃいました笑\n\n大阪の、たこ焼きの中でもぺちゃ焼きというのがあって、\n\nなにこれなにこれ！！！\n\nってなりながら買っちゃいました笑\n\n美味しかったーーーー；＿；\n\nこれも写真撮るの忘れてしまった…\n\nつぎはタコせんにチャレンジしたいですね！"
