     "t": "こんばんは！\n\n昨日、\n\n昨日ミュージカルテニスの王子様全国大会青学VS立海公演が\n\n全て終了しました。\n\n69公演、応援してくださった皆様本当にありがとうございました！\n\n皆様の声援があったからこそ、\n\n無事乗り越えられたと思っています！\n\nいま本当に終わったんだなと、\n\n少しずつ実感し、一人で泣きそうです笑\n\n四天宝寺は、最後に加わったチームで、\n\n他のチームよりは短い時間ではありましたが、\n\nそれ以上に密度濃い時間を過ごしました。\n\n最初はバラバラだったチームも、\n\n今では本当に家族のようです。\n\n皆で笑い、皆で考え、皆でご飯を食べる。\n\n本当に家族より多くの時間を過ごしていました。\n\n色々なことがありましたが、いまではとてもいい経験と、思い出になりました。\n\nそしてですね。\n\n今日起きてから感じた事なのですが、\n\n今日起きてまず時計をみて、\n\nそっか、今日は休演日←\n\n明日は6時公演だから、今日は何しようっていう事を考えていてですね。\n\nビックリしました笑笑\n\nここまで生活の1部として、なっていたとは…\n\nそれほどテニミュの事を今までずっと考えていました！"
