     "t": "このパネル！\n\nこういうのを見つけると顔を突っ込んでみたくたってしまう東です。笑\n\nまあ1人でこんなことをしていたら\n通りがかった人がチラ見のオンパレードですよ！笑\n\nしかし右のほうにこっちをずっと見つめてくる人が。\n\nおや？\n\nなんだろこの恥ずかしい気持ち\n\nあれ？\n\nでも見覚えのある人だ…\n\nワオ！\nパニック！！！"
