     "t": "2015-04-23 22:07:16\nテーマ：ブログ\n\nこんばんは！！\n\n今日は皆さんにお知らせです！！\n\nまずは！！\n\n遅くなりましたが、\n\n舞台「ラズベリーボーイ２」に出演が決まりました！！\n【日程】\n2015年7月15日（水）～7月20日（月・祝）\n【会場】\n俳優座劇場（六本木）\n【出演者】\n林明寛・磯貝龍虎・高崎翔太・早乙女じょうじ・寺山武志・東啓介\n小野一貴・塩田康平・樋口裕太・北園涼・秋葉友佑 ／ 富田翔　他\n\n物凄く嬉しいです。\n\nまたみなさんの前に立てる時間が増えました。\n\n東頑張ります。\n\nそして、初日前日は誕生日！！！\"((∩´︶`∩))\"\n\n楽しみですねーｳｼｼ((≧艸≦*))ｳｼｼ\n\nと言うことで、ラズベリーボーイ2！お楽しみに！\n\nさてー、今日はですねー。\n\n初のお仕事が決まりまして！\n\n何かと言うと、、、、\n\nラジオ！！！！\n\nFM西東京さんにて、土曜日の9時から放送されている。\n\nおたママ倶楽部に5/2.5/9と出演させていただきます！！\n\n西東京だけしか流れないのかなと思いきや！\n\nスマートフォンでも、パソコンでも聞けるということなので、\n\n是非是非、チェックしてみてください！\n\n僕のいままでに話していない話題なんかもありますので、\n\nそちらもお楽しみに\"((∩´︶`∩))\"\n\nそれではばーーいばーーーい！"
