     "t": "こんばんは！\n\n妖の単独ライブ！\n\n先行予約が始まってますよーーー！\n\n先行予約ば期間が短いのでお早めにね！(￣^￣)ゞ\n\nいやーー、\n\nなにしたいかなー！\n\nやっぱ霊示的にはお皿を紡ぎたいのかな？\n\nなんて笑\n\n僕がもし体を貸してくれたら何か願いを叶えてあげるって言われたら、\n\nまた新しい曲を歌って欲しいですね。\n\n何がいいかな？笑\n\n皆さんは何を歌って欲しいですか？\n\n僕は…………まだ秘密。ｳｼｼ((≧艸≦*))ｳｼｼ\n\nあとは何かなー、\n\nドラマパート面白かったから本当に舞台で演出つけてやれたらいいなーなんて、\n\nそれは僕らが役者であるから、\n\n自分達の成長にもつながるし！\n\nそれは最高や！笑\n\nまだまだこれからみんなと話して作っていくんだけど\n\n実現する？かも？\n\n実現しますよーーーに！\n\nたなＰにお願いしておかなきゃな～ｳｼｼ((≧艸≦*))ｳｼｼ"
