     "t": "こんばんは！\n\nペダル稽古も終盤に差し掛かってきましたね。\n\nみんなが合流して、とても良い感じでございます。\n\n僕ももっと葦木場くんと仲良くなるために、\n\n移動中も原作や台本を読んでます。\n\n難しいですね。うん。なんだろう。共通点があるからこそ、仕草みたいなものが見つかりにくい。\n\nでも僕なりの葦木場くんを作り上げます。\n\n演出家さんにも以前は葦木場のキャラと全く違うと断言されてしまいましたが、\n\n別のアプローチを考え提出、考え提出を繰り返しています。\n\n今この瞬間でも葦木場くんだったら、なんて考えて生活するようにもなりました。\n\n優しくて、ホワホワしてて、でもレースになるとはしゃいじゃう葦木場。\n\n好きです。\n\n僕は上手くないし、不安になる事が多くあります。\n\nでもね。\n\n同じ箱学のうえちゃんやたーくんや兼崎さんが助けてくれる。\n\nとても嬉しいです。\n\nだから、もっと葦木場くんの事を、考えるんだ。"
