    {
     "t": "箱学本当好き。\n\n素でいられるますし、\nチームでいると落ち着きます。\n\nまだまだ、この熱い作品を届けていきたいと思ってますので、\n\n大阪の皆さん！そして、\n神奈川の皆さん！楽しみに待っていてください！！！！\n\nそれでは。"
    }
