     "t": "©舞台『刀剣乱舞製作委員会』\n\n『かっこよく決めたいよね』\n\n撮影のときは\nどうしたら光忠くんにより近づくことが出来るかを考えながら\n\nスタッフさんと\nとにかくカッコ良い\nポーズにこだわりました。\n\nだからこそ\n僕も完成をずっと楽しみにしてて\n\nやっと皆さんにお見せすることができて嬉しいです。\n\nもっともっとビジュアル面、\n内面を研究して、\n僕なりの光忠くんを演じていきたいと思います。\n\n楽しみにしてください！\n\nそして、、\n\nすでにご存知の方も\nいらっしゃるとは思いますが\n本日、オーディションの時からずっと\n一緒だった楡木直也が\n芸能活動から卒業することが発表それました。\n仲間の卒業は残念ですが\nそれぞれの場所で、僕も変わらずに精一杯頑張りたいと想います。\n\nまずは\n弱虫ペダル神奈川初日！\nいってきますね！\n\n第九で気合い入れますよ！\n\nそれでは。"
