     "t": "こんばんは！\n\n今日は稽古からの\nレッスンでした。\n\n稽古はアクションを中心に\n日々戦っています！！\n普段のアクションとは\nまた少し変わっていて難しいけど、とてもやりがいがあります。\n\nだんだんと次のステップへと進んでいるので\n日々の稽古が楽しいです！\n\nお気づきの方もいるかと思いますが\nTwitterに続き、ブログも遂に\n刀剣乱舞仕様に変わりましたし！\n\n新しい環境で出会いもたくさんあり、これからがますます楽しみですね。\n\nそして、レッスン！！\n\nレッスンも\n自分の成長が目に見えてわかるのでテンション上がる。\n\nもっとやりたい、\nもっといろんなことに挑戦したい。\n\nよーーーし！\n\n映画みよーっと。"
