     "t": "こんばんは、\n\n昨日は、顔合わせでした。\n\n多くのスタッフさんやキャストでいっぱいになる稽古場をみて、\n\nこれだけ多くの人が関わっているんだと、\n身が引き締まりました。\n\n稽古も中盤ですが、\nまだまだやることが一杯です。\n\n殺陣はもちろんのこと、\n\n尊敬する先輩役者さんがたくさんいらっしゃる中で\nお芝居ができるのはとても嬉しいです！\nでも、なかなか思い通りにできない。\n\nもっと考えて、一歩一歩進んでいきます。\n\nつまづいた時にこそ\n面白い何かが見つかるんじゃないかと信じて！\n\n落ち込んでる場合じゃないな！\n\n失敗して何歩か下がることはいいと思うけど、考えることをやめて立ち止まることはしたくない。\n\nがむしゃらに進む。\n\nやろう。\n\nまぁ！毎日充実してることには変わりませんがね\"((∩´︶`∩))\"\n\n楽しい事ばかり！\n新しい発見も沢山。\n\nあと約二週間！丁寧に挑んでいきます！"
