     "t": "写真を撮っていたらテルマくん乱入笑\n\n隠し撮りしてます笑\n\n昨日は、高校時代の親友が語学留学で海外へと出発しました。\n\n残念ながら空港まで行く事は出来ませんでしたが、\n\n本番終了後、電話で思いを伝えました。\n\n1人で海外にいく事に少し不安がっていましたが、彼なら乗り越えられると信じています。\n\nそんな彼に刺激を毎日受けていました。\n\n僕ももっと努力をして、\n目標へとたどり着けるよう精進せねばと、\n再確認できました。\n\nありがとう。\n\n皆様も、\n辛いと感じた時は\n身近な人や頑張ってる人の姿をみて、よし！まだまだ！と思って\n前を向いて行きましょう！\n\nそれでは今日も劇場で待っています！"
