    {
     "img": "assets/img/blog/ec76b871f2f0fe86.jpg"
    },
    {
     "t": "殺陣も苦戦したけど、楽しんでできたし、\n\n何より長谷部くんと殺陣ができてよかった。\n\n大阪の軍議も楽しみだなー笑\n\nなにが出るかなー？ｳｼｼ((≧艸≦*))ｳｼｼ\n\n最近、\n物を見ると、心があったらどう思うんだろうなーって考える事が増えました。\n\nいま触ってる携帯とかなにを思ってるのかなーって笑\n\n身の回りの物を大切にしようって思います。\n\nうし！\n\n大阪も頑張るぞ！"
    },
    {
     "img": "assets/img/blog/d242652ba10889df.jpg"
    }
