    {
     "t": "こんにちは！！\n\nTwitterでも、\nお知らせさせていただきましたが、\n\n東啓介、また原田左之助として、薄桜鬼に帰ってきます！！\n\nまた柏木さん演じる不知火と戦えるのか。。\n\nさらに、白又くんも帰ってくることですし、\n共演できることが嬉しいです。\n\n今から楽しみで仕方がありません！！\n\nしかも！\n\nライブということで、皆様と一緒に\n盛り上がれるなんて楽しみで仕方がありません！\n\nミュージカル『薄桜鬼』黎明録、新選組奇譚の\n楽曲を中心に、\n歴代公演の楽曲を\nライブコンサート用に\n一新という事で、\nどのような曲がくるのかいまから楽しみです！！"
    },
    {
     "img": "assets/img/blog/8159b4ca13fd7ab7.jpg"
    },
    {
     "t": "よろしくね。"
    }
