     "t": "こんばんは！\n\n今日は、\n『Club Slazy ーAWー』の話をしていこうかな。\n\n今回、この作品に始めて参加させていただきました。\n\nでも、ずーーっと、知っていて、\n\nそして、出演できたらなとずーーっと、思ってました。\n\nだから、出演が決まった時とは本当に嬉しかったです。\n\nダンス、歌、お芝居と、盛り沢山なこの作品。\n\n周りのキャストさんや、\nスタッフさんがいたからこそ僕はのびのびと演技できていたと思います。\n\n1番年下の僕に良輔くんや、健くんが仲良くしてくれて、\n\nいい意味で、甘えることができました。\n\nKimeruさんや、まさしくんはつねに背中を見さていただきました。\n\n毎回相談に乗ってくれましたし。\n\n本当に副大統領でした。\n\nサムさんやこうへいくんも本当によくしてくださいました。\n\nまさくんも優しく話しかけてくれましたし。\n\n最高です。笑"
