   "blocks": [
    {
     "t": "ミュージカル『マタハリ』全公演無事終了しました。\n\n応援してくださった皆様、観に来てくださった皆様、本当にありがとうございました。\n\n本当に幸せな時間を過ごさせていただきました。\nグランドミュージカル2作品目にして、こんなにも大きな役を与え下さったこと。本当に感謝しかありません。\n\n最初は不安、プレッシャー、などたくさんのネガティブな想いがありました。\n僕がこの公演を乗り越えられたのは、\n\n石丸さん、柚希さん、加藤さん、佐藤さんはもちろん、メインの方々、アンサンブルの皆様、スタッフさん、全ての方に支えられたからです。\n\n感謝しきれません。\n\nそして、ファンの皆様の大きな大きな応援メッセージがあったから僕はもっと上へ、上へと目指すことができました。\n\nありがとうございます。\n\n今回の作品で素敵な出会いがたくさんありました。"
    },
    {
     "lost": 1
    },
    {
     "t": "ちえさん(柚希礼音さん)\n\n僕が言うのも失礼ですが、本当にお茶目で、可愛らしくて、ストイックで、どんな事にも果敢に負ける事なく挑んで行く姿が素敵でした。\n若手の僕にも仲良くなんでも話し合ってくれて、嬉しかったですし、ちえさんが相手役で本当に幸せでした。\n屋上のシーンもいつも最高に幸せでした。\nまた絶対に共演したいです。"
    },
    {
     "lost": 1
    },
    {
     "t": "シュガーさん(佐藤隆紀さん)\n\n一緒に板の上に立つことは出来ませんでしたが、稽古場から気さくに声をかけてくれて、仲良くしてくださいました。\n歌もたくさん聴いていただきました。\nシュガーさんの歌声は本当に素敵でした。\nまた共演したいですし、一緒に板の上に立ちたいです。"
    },
    {
     "lost": 1
    },
    {
     "t": "和音美桜さん\n舞台上では絡めませんでしたが、稽古場から明るく、気さくに話しかけてくれました。\n嬉しかったです。\nいつもマタハリに歌う歌が好きでした。\n和音さんとも、また共演したいです！！！"
    },
    {
     "lost": 1
    },
    {
     "t": "くりさん(栗原英雄さん)\nくりさんも舞台上では絡めませんでしたが、京都で一緒にお酒を飲ませて頂いたこと忘れません。\n今作では歌はありませんでしたが本当に毎回お芝居を変化していて、尊敬しました。\n『とん！ おはよう\"((∩´︶`∩))\"』といつも言ってくださり、幸せでした。\nまたご一緒したいです。\n\n福井さん(福井晶一さん)\n\nお写真が撮れなかった、、、、\nそれくらい劇中ではアルマンとの絡みが全くないのです、、、、。\nですがいつも、モニターで『捕らえろスパイ』を聞いていました。\n稽古中にとんちゃんのナチュラルなお芝居結構好きだよと言ってくださって嬉しかったです。\nミュージカルの技術を福井さんを見て聞いて勉強させて頂いてました。\n成長してまたご一緒したい。"
    },
    {
     "lost": 1
    },
    {
     "t": "和樹くん(加藤和樹さん)\n\n本当に本当に沢山お世話になりました。\n稽古中、本番中、ほぼずっと一緒にいました。\nただでさえ、二役を演じ分けるのが大変な中、僕にアドバイスを沢山くれたり、ご飯に連れて行ってくださったり。\n兄のような存在でした。かずきくんがいなかったら今の僕はいないでしょう。\n和樹くんとお芝居をするのが本当に楽しかったし、幸せでした。僕を奮い立たせてくれました。\n二役に果敢に挑む和樹くんの背中を見て、追っかけていました。\nもっとやりたかった、もっと深められた。\nまた必ず、絶対に共演したい。\n頑張ろう。"
    },
    {
     "lost": 1
    },
    {
     "t": "そしてさちこさん。\nスカピンに続いて、マタハリも一緒にお仕事ができてとても嬉しかった。\nたくさんのダメ出し、ノートを、頂きました。\nいつも役者に寄り添って、一緒に役を深めてくださいました。\nたくさん悩んで、考えて、わからなくなって、でもそんな時間も幸せでした。\nさちこさんがいたから僕は成長する事が出来ました。"
    },
    {
     "lost": 1
    },
    {
     "t": "他にもたくさん書きたい方います。\nでも書いたらきりがないのでこの辺で、、、\n\nなんども書いてますが、また皆様と共演したい。\n\n本当に一人一人が素敵な方達でした。\nこんなにも素敵で幸せなカンパニーの中でアルマンを演じられたこと、僕の財産です。\n全ての出会いに感謝です。\n\nありがとう。アルマン。最高にかっこいい人だった。\nまだまだ背中を追っかけていたいです。\n本当にありがとう。"
    }
   ]
